def solve_van_pairs(text):
    tokens = text.split()
    n, cap = int(tokens[0]), int(tokens[1])
    w = sorted(int(t) for t in tokens[2:2 + n])
    i, j = 0, n - 1
    vans = 0
    while i <= j:
        if i < j and w[i] + w[j] <= cap:
            i += 1
        j -= 1
        vans += 1
    return str(vans)

